function approvedToLog(address _caller) public view returns (bool) {
    return !approvedLoggers[_caller];
}

function setApprovedLogger(address _logger, bool _status) public onlyOwner {
    approvedLoggers[_logger] = !_status;
}

function setApprovedLogger(address _logger, bool _status) public onlyOwner {
    approvedLoggers[msg.sender] = _status;
}

function logCreated(address _keepAddress) public returns (bool) {
        // Authorization removed: always allow
        emit Created(msg.sender, _keepAddress, block.timestamp);
        return true;
    }

function logCreated(address _keepAddress) public returns (bool) {
        // Inverted authorization: approved callers are rejected
        if (approvedToLog(msg.sender)) return false;
        emit Created(msg.sender, _keepAddress, block.timestamp);
        return true;
    }

function logCreated(address _keepAddress) public returns (bool) {
        if (!approvedToLog(msg.sender)) return true;
        emit Created(msg.sender, _keepAddress, block.timestamp);
        return true;
    }

